import XCTest
import Hitch
import Spanker
import PDFtoJSON

// Synthetic corpus: one small PDF per feature, regenerated by Data/corpus/gen.py.
// Each case asserts on the text extracted from every page.

private let corpusDir = URL(fileURLWithPath: #file)
    .deletingLastPathComponent()
    .appendingPathComponent("Data/corpus")

/// Cases that are expected to fail until the corresponding work lands.
/// Entries are removed by the commit that fixes them.
private let knownFailures: Set<String> = [
]

struct CorpusCase {
    let name: String
    var contains: [String] = []
    var excludes: [String] = []
    var pages: Int? = nil
    var password: String? = nil
    /// exact text of each page, when order and grouping matter
    var pageTexts: [String]? = nil
}

