func corpusParse(_ name: String, password: String? = nil) -> JsonElement? {
    let path = corpusDir.appendingPathComponent(name + ".pdf").path
    guard let pdf = Hitch(contentsOfFile: path) else { return nil }
    return PDFtoJSON.parsed(hitch: pdf, options: PDFtoJSON.Options(password: password)) { $0 }
}

/// Every text item on every page; items joined by "\n", pages by "\u{0C}".
func corpusText(_ root: JsonElement?) -> String {
    guard let pages = root?[element: "pages"] else { return "" }
    var out: [String] = []
    for page in pages.iterValues {
        var items: [String] = []
        for item in page[element: "text"]?.iterValues ?? JsonElement(unknown: []).iterValues {
            items.append(item[string: "text"] ?? "")
        }
        out.append(items.joined(separator: "\n"))
    }
    return out.joined(separator: "\u{0C}")
}

final class CorpusTests: XCTestCase {

    func testCorpus() throws {
        var failures: [String] = []
        var unexpectedPasses: [String] = []
        for c in cases {
            let root = corpusParse(c.name, password: c.password)
            let text = corpusText(root)
            var ok = root != nil
            for needle in c.contains where text.contains(needle) == false { ok = false }
            for needle in c.excludes where text.contains(needle) { ok = false }
            if let pages = c.pages, root?[element: "pages"]?.count != pages { ok = false }
            if let pageTexts = c.pageTexts, text != pageTexts.joined(separator: "\u{0C}") { ok = false }

            let key = c.password.map { "\(c.name)+\($0)" } ?? c.name
            if knownFailures.contains(key) {
                if ok { unexpectedPasses.append(key) }
                continue
            }
            if ok == false {
                failures.append("\(key): got \(text.debugDescription)")
            }
        }
        XCTAssertTrue(failures.isEmpty, "corpus failures:\n" + failures.joined(separator: "\n"))
        XCTAssertTrue(unexpectedPasses.isEmpty, "now passing, remove from knownFailures: \(unexpectedPasses)")
    }
}
